import React, {Component} from 'react';
import { Card, Button, Col, Container } from 'react-bootstrap';
import { DivCenterPR } from '../../_assets/js/StylesDiv';
import api from '../../_config/api/binance';
import './styles.css';

class Carteira extends Component {
    
    state = {
        digimons: [
            {
            
            }
        ]
    }
        async componentDidMount(){
            const digimons_api = await api.get('digimon');

            this.setState({
                digimons: digimons_api.data
            })
        }

    render () {
        return (
        <>
                <DivCenterPR className="ajust-card">
                    {this.state.digimons.map( digimon =>
                 
                        <C>
                            <Card>
                                <Card.Img className="confg-img" src={digimon.image} />
                                <Card.Body className="confg-card">
                                    <Card.Title>{digimon.name}</Card.Title>
                                    <Card.Text>{digimon.symbol}</Card.Text>
                                    <Card.Text>{digimon.current_price}</Card.Text>
                                    <Button variant="primary">Ver Digimon</Button>
                                </Card.Body>
                            </Card>
                        </C>
                    )}
                </DivCenterPR>
        </>
        )
    }
}

export default Carteira;
